def f(g):
    h,w=len(g),len(g[0])
    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2]
    rows_pts={}
    for r,c in pts: rows_pts.setdefault(r,[]).append(c)
    b=max([r for r,v in rows_pts.items() if len(v)>=2],default=None)
    out=[row[:] for row in g]
    cs=sorted(rows_pts[b])
    for c in range(cs[0],cs[-1]+1):
        if out[b][c]==0: out[b][c]=3
    for r,c in pts:
        if r==b or out[r][c]!=0: continue
        step=1 if r<b else -1
        rr=r+step
        while rr!=b:
            out[rr][c]=3; rr+=step
    return out
